import heapq
from collections import defaultdict

class Solution:
    def minCost(self, maxTime: int, edges: List[List[int]], passingFees: List[int]) -> int:
        n = len(passingFees)
        g = defaultdict(list)
        for x, y, t in edges:
            g[x].append((y, t))
            g[y].append((x, t))
        best_time = [maxTime + 1] * n
        pq = [(passingFees[0], 0, 0)]
        while pq:
            cost, time, u = heapq.heappop(pq)
            if u == n - 1:
                return cost
            if time > best_time[u]:
                continue
            best_time[u] = time
            for v, t in g[u]:
                nt = time + t
                if nt <= maxTime and nt < best_time[v]:
                    heapq.heappush(pq, (cost + passingFees[v], nt, v))
        return -1

