class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(new int[]{e[1], e[2]});
            g.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] bestTime = new int[n];
        Arrays.fill(bestTime, Integer.MAX_VALUE);
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{passingFees[0], 0, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int cost = (int) cur[0], time = (int) cur[1], u = (int) cur[2];
            if (u == n - 1) return cost;
            if (time > bestTime[u]) continue;
            bestTime[u] = time;
            for (int[] nb : g.get(u)) {
                int nt = time + nb[1];
                if (nt <= maxTime && nt < bestTime[nb[0]])
                    pq.offer(new long[]{cost + passingFees[nb[0]], nt, nb[0]});
            }
        }
        return -1;
    }
};

