var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const g = Array.from({length: n}, () => []);
    for (const [x, y, t] of edges) {
        g[x].push([y, t]);
        g[y].push([x, t]);
    }
    const heap = [];
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = 2 * i + 2;
                let m = i;
                if (l < heap.length && heap[l][0] < heap[m][0]) m = l;
                if (r < heap.length && heap[r][0] < heap[m][0]) m = r;
                if (m === i) break;
                [heap[m], heap[i]] = [heap[i], heap[m]];
                i = m;
            }
        }
        return top;
    };
    const bestTime = new Array(n).fill(Infinity);
    push([passingFees[0], 0, 0]);
    while (heap.length) {
        const [cost, time, u] = pop();
        if (u === n - 1) return cost;
        if (time > bestTime[u]) continue;
        bestTime[u] = time;
        for (const [v, t] of g[u]) {
            const nt = time + t;
            if (nt <= maxTime && nt < bestTime[v]) push([cost + passingFees[v], nt, v]);
        }
    }
    return -1;
};
